#!/usr/bin/env python3
"""Standalone offline Canvas 3D inspector for REAL v82 V52 mesh triangles and 12 ends."""
from pathlib import Path
import json, numpy as np, trimesh
R=Path(__file__).resolve().parents[1]
s=trimesh.load(R/'model/BNBU_v83_FULL_EDITABLE.glb',force='scene',process=False)
records=json.loads((R/'qa/v83_v52_probe.json').read_text())
tri=[]
for n in sorted({r['bridge_node'] for r in records}):
 tf,k=s.graph[n];m=s.geometry[k];v=trimesh.transform_points(m.vertices,tf)
 for fi,t in enumerate(m.faces):
  tri.append([n,int(fi),'bridge'] + np.round(v[t].reshape(-1),4).tolist())
for r in records:
 for f in [*r['candidate_model_neighbors'][:2]]:
  key=(f['node'],f['source_face_index'])
  if key in [(z[0],z[1]) for z in tri]:continue
  tf,k=s.graph[f['node']];m=s.geometry[k];v=trimesh.transform_points(m.vertices,tf)
  tri.append([f['node'],f['source_face_index'],'neighbor'] + np.round(v[m.faces[f['source_face_index']]].reshape(-1),4).tolist())
# Source GLB is authoritative; HTML vertices merely rounded 4 d.p. for display.
data={'title':'V52 twelve bridge-end probes','parent':'v82','tris':tri,'probes':records}
raw=json.dumps(data,ensure_ascii=False,separators=(',',':'))
T=r'''<!DOCTYPE html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BNBU v83 · V52 12桥端真实源三角面</title><style>
*{box-sizing:border-box}body{margin:0;background:#101f30;color:#e2edf4;font-family:system-ui,"Microsoft YaHei",sans-serif}header{padding:12px 18px;background:#12283a;border-bottom:1px solid #365166}h1{font-size:18px;margin:0 0 4px}small{color:#aac4d4}main{display:flex;height:calc(100vh - 66px)}#scene{position:relative;flex:1;min-width:0;background:#dbe7e7}canvas{width:100%;height:100%;touch-action:none;cursor:grab}aside{width:360px;overflow:auto;padding:15px 18px}select,button{background:#183749;border:1px solid #5a7c93;color:white;padding:8px;border-radius:7px}select{width:100%}button{margin:6px 6px 7px 0;cursor:pointer}p{font-size:13px;line-height:1.55}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.55;color:#afc9dd}#status{position:absolute;bottom:12px;left:12px;background:#102438e6;color:white;padding:7px 10px;border-radius:7px;font-size:12px}label{display:block;margin:9px 0;font-size:13px}@media(max-width:800px){main{flex-direction:column}#scene{min-height:48vh}aside{width:auto;max-height:45vh}}
</style></head><body><header><h1>BNBU v83 · V52 12桥端三角面定位</h1><small>离线 CPU 3D · 蓝色为原有桥面源三角面，橙色为最近的其他原有源三角面。非实测道路连通性。</small></header><main><div id="scene"><canvas id="c"></canvas><div id="status">加载真实源三角面…</div></div><aside><b>桥端样本</b><p><select id="pick"></select></p><button id="next">下一个端点</button><button id="all">全部六座桥</button><label><input id="neighbors" type="checkbox" checked> 显示最近候选表面</label><label><input id="ids" type="checkbox" checked> 显示 12 个端点标记</label><p>左键拖动旋转，右键拖动平移，滚轮缩放。所示仅为继承模型的精确三角面拓扑，屏显坐标四舍五入。</p><hr><b>几何来源与可通行性</b><pre id="info"></pre><p>官方手绘图仅作拓扑约束；该 0.04–0.15 模型米间距来自同一个未测绘的 GLB，不能视作桥端实测净空，也不能自动建立步行网络。</p><p><a style="color:#80caec" href="https://www.bnbu.edu.cn/en/images/shouhuiditu2025.jpg" target="_blank">官方 2025 手绘校园图</a></p></aside></main><script>const DATA=__JSON__;const c=document.getElementById('c'),ctx=c.getContext('2d');const byId=x=>document.getElementById(x);let yaw=-0.85,pitch=1.13,zoom=22,center=[0,0,4],selected=0,all=false,drag=null,last=0;
const BRIDGE_NAMES=[...new Set(DATA.probes.map(x=>x.bridge_node))];const pick=byId('pick');for(let i=0;i<DATA.probes.length;i++){let o=document.createElement('option');o.value=i;o.textContent=DATA.probes[i].id+' · '+DATA.probes[i].bridge_node.split('CONNECTION_')[1].slice(0,2);pick.append(o)};
function fit(){let r=c.getBoundingClientRect(),d=devicePixelRatio||1;c.width=Math.max(250,Math.floor(r.width*d));c.height=Math.max(240,Math.floor(r.height*d));draw()};const clamp=(a,b,c)=>Math.max(b,Math.min(c,a));
function proj(a){let x=a[0]-center[0],y=a[1]-center[1],z=a[2]-center[2],cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),sc=zoom*devicePixelRatio;return [c.width/2+(-x*sy+y*cy)*sc,c.height/2-( -x*sp*cy-y*sp*sy+z*cp)*sc,(x*cy+y*sy)*cp+z*sp]}
function focus(i){selected=i;all=false;let r=DATA.probes[i];center=[...r.xyz_local_model];zoom=clamp(Math.min(c.width,c.height)/(50*(devicePixelRatio||1)),5,40);pick.value=i;draw()}
function draw(){ctx.fillStyle='#e0e9e9';ctx.fillRect(0,0,c.width,c.height);let r=DATA.probes[selected],visible=[];
for(let t of DATA.tris){if(!all&&t[0]!==r.bridge_node&&t[2]!=='neighbor')continue;if(t[2]==='neighbor'&&!byId('neighbors').checked)continue;let p=proj(t.slice(3,6)),q=proj(t.slice(6,9)),s=proj(t.slice(9,12));if(!all&&t[2]==='neighbor'&&Math.max(...[p,q,s].map(z=>Math.hypot(z[0]-c.width/2,z[1]-c.height/2)))>c.width*.8)continue;let ar=(q[0]-p[0])*(s[1]-p[1])-(q[1]-p[1])*(s[0]-p[0]);if(Math.abs(ar)<.04)continue;visible.push([Math.min(p[2],q[2],s[2]),t,p,q,s])}visible.sort((a,b)=>a[0]-b[0]);
for(let [depth,t,p,q,s] of visible){ctx.beginPath();ctx.moveTo(p[0],p[1]);ctx.lineTo(q[0],q[1]);ctx.lineTo(s[0],s[1]);ctx.closePath();ctx.fillStyle=t[2]==='neighbor'?'rgba(235,135,69,.88)':'rgba(54,127,169,.75)';ctx.fill();ctx.strokeStyle=t[2]==='neighbor'?'#c96a37':'#48778a';ctx.lineWidth=.4;ctx.stroke()}
if(byId('ids').checked)for(let probe of DATA.probes){if(!all&&probe.bridge_node!==r.bridge_node)continue;let p=proj(probe.xyz_local_model);ctx.beginPath();ctx.arc(p[0],p[1],5,0,Math.PI*2);ctx.fillStyle=probe.id===r.id?'#d72d36':'#0c744f';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=1.3;ctx.stroke();ctx.font='bold 13px system-ui';ctx.fillStyle='#10283e';ctx.fillText(probe.id,p[0]+7,p[1]-8)}
byId('status').textContent=DATA.tris.length+' 实际源面样本 / '+visible.length+' 可见面 | main GLB保持1347网格不变 | 12个桥端均未证实可通行';let near=r.candidate_model_neighbors[0];byId('info').textContent='端点：'+r.id+'\n原网格：'+r.bridge_node+'\n源三角面：'+r.source_face_index+'\n源面法向：'+r.source_face_normal_xyz.map(x=>x.toFixed(3)).join(', ')+'\n局部模型 XYZ：'+r.xyz_local_model.map(x=>x.toFixed(3)).join(', ')+'\n估计模型层级：'+(r.model_z>3?'Level 2 proxy':'Uncertain')+'\n\n最近向上表面：'+(near?near.node:'没有')+'\n面 ID：'+(near?near.source_face_index:'—')+'\n3D模型距离：'+(near?near.distance_3d_model_m+' m':'无')+'\n模型相对高差：'+(near?near.delta_z_model_m+' m':'无')+'\n\n结论：不具备测绘和现场入口证据；无法确认可通行。';window.__BNBU_V83__={ready:true,version:'v83',sourceProbes:12,visibleTriangles:visible.length,selected:r.id,webgl:false};}
function pointPos(e){let r=c.getBoundingClientRect();return [e.clientX-r.left,e.clientY-r.top]};c.onpointerdown=e=>{c.setPointerCapture(e.pointerId);drag={p:pointPos(e),button:e.button}};c.onpointermove=e=>{if(!drag)return;let p=pointPos(e),dx=p[0]-drag.p[0],dy=p[1]-drag.p[1];drag.p=p;if(drag.button===2||e.shiftKey){let k=1/zoom;center[0]+=(Math.sin(yaw)*dx+Math.cos(yaw)*dy)*k;center[1]+=(-Math.cos(yaw)*dx+Math.sin(yaw)*dy)*k;}else{yaw-=dx*.006;pitch=clamp(pitch+dy*.005,.15,1.52)}draw()};c.onpointerup=()=>drag=null;c.oncontextmenu=e=>e.preventDefault();c.onwheel=e=>{e.preventDefault();zoom=clamp(zoom*Math.exp(-e.deltaY*.001),1,120);draw()};pick.onchange=e=>focus(+e.target.value);byId('next').onclick=()=>focus((selected+1)%12);byId('all').onclick=()=>{all=true;center=[75,-40,4];zoom=1.5;draw()};byId('neighbors').onchange=draw;byId('ids').onchange=draw;window.addEventListener('resize',fit);fit();focus(0);</script></body></html>'''
(R/'viewer'/'BNBU_v83_V52_Actual_Triangle_3D_Inspector.html').write_text(T.replace('__JSON__',raw),'utf8')
print('viewer triangles',len(tri),'bytes',len(raw))